type Service = { name: string, port: int, public: bool, replicas?: int = 1 }
type Subnet = { base: string, prefix: int }
type Site = {
    name: string
    network: Subnet
    services: Service[]
    ratio: float
    limit: int
    enabled: bool
    note?: string
    tags: string[]
    labels: { [string]: string }
    latency: quantity<Time>
    primary: ref<Service>
}
func label(s: Service): string = `${s.name}:${s.port}`
func cidr(net: Subnet): string = `${net.base}/${net.prefix}`
@render({ template: "site.txt" })
export output site: Site = {
    name: "edge", network: { base: "10.0.0.0", prefix: 8 },
    services: [{ name: "a", port: 80, public: true }, { name: "b", port: 443, public: false, replicas: 3 }],
    ratio: 0.25, limit: 12000, enabled: true, tags: ["x", "y"], labels: { k: "v" },
    latency: 250ms, primary: services[1],
}

