files.site.decl:
type Service = { name: string, port: int, public: bool, replicas?: int = 1 }
type Subnet = { base: string, prefix: int }
type Site = {
    name: string
    network: Subnet
    services: Service[]
    ratio: float
    limit: int
    enabled: bool
    note?: string
    tags: string[]
    labels: { [string]: string }
    latency: quantity<Time>
    primary: ref<Service>
}
func label(s: Service): string = `${s.name}:${s.port}`
func cidr(net: Subnet): string = `${net.base}/${net.prefix}`
func ports_csv(ss: Service[]): string = std.string.join([std.string.of(s.port) for s in ss], ",")
@render({ template: "nginx.conf.j2" })
export output site: Site = {
    name: "edge", network: { base: "10.0.0.0", prefix: 8 },
    services: [{ name: "a", port: 80, public: true }, { name: "b", port: 443, public: false }, { name: "c", port: 8080, public: true, replicas: 2 }],
    ratio: 0.25, limit: 1, enabled: true, tags: [], labels: {}, latency: 1ms, primary: services[0],
}

files.nginx.conf.j2:
